const get_human_revision_pages_url = () => {
  try {
    const value = globalThis.__HUMAN_REVISION_PAGES_BASE_URL__;
    if (typeof value !== 'string' || !value.trim()) return '';
    const url = new URL(value.trim());
    return url.protocol === 'https:' ? url.href.replace(/\/+$/, '') : '';
  } catch {
    return '';
  }
};
const human_revision_pages_url = get_human_revision_pages_url();
const variable_structure_urls = [
  ...(human_revision_pages_url ? [`${human_revision_pages_url}/human-revision/schema/index.js`] : []),
  'https://raw.githubusercontent.com/NicholasKoji/tavern_helper_template/codex/zaohua-nongren/dist/人间修订中/脚本/变量结构/index.js',
  'https://fastly.jsdelivr.net/gh/NicholasKoji/tavern_helper_template@codex/zaohua-nongren/dist/人间修订中/脚本/变量结构/index.js',
  'https://gcore.jsdelivr.net/gh/NicholasKoji/tavern_helper_template@codex/zaohua-nongren/dist/人间修订中/脚本/变量结构/index.js',
  'https://testingcf.jsdelivr.net/gh/NicholasKoji/tavern_helper_template@codex/zaohua-nongren/dist/人间修订中/脚本/变量结构/index.js',
];
const load_variable_structure = async () => {
  for (const url of variable_structure_urls) {
    try {
      await import(`${url}?t=${Date.now()}`);
      return;
    } catch (error) {
      console.warn('变量结构加载回退', url, error);
    }
  }
  console.error('变量结构加载失败');
};
load_variable_structure();
